    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            a[i] = (long) in.nval;
        }
        List<List<long[]>> groups = groupPairs(a);
        StringBuilder sb = new StringBuilder();
        for (List<long[]> g : groups) {
            for (int k = 0; k < g.size(); k++) {
                if (k > 0) sb.append(' ');
                sb.append('(').append(g.get(k)[0]).append(',').append(g.get(k)[1]).append(')');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}
